        urlopen.return_value = FakeResponse(
            {
                "data": [
                    {
                        "id": "publisher/model",
                        "object": "model",
                        "owned_by": "publisher",
                        "created": 123,
                    }
                ]
            }
        )
        provider = LMStudioProvider(
