"""Read-only Docker image and container inventory via the Docker CLI."""

from __future__ import annotations

import json
import math
import re
import subprocess
from dataclasses import dataclass
from json import JSONDecodeError
from typing import NoReturn

from .errors import (
    ProviderFailureError,
    ProviderUnavailableError,
    UnsupportedOperationError,
)
from .models import ModelRecord, Operation, ProviderResult

DEFAULT_TIMEOUT = 10.0
_JSON_TEMPLATE = "{{json .}}"
_IMAGE_COMMAND = (
    "docker",
    "image",
    "ls",
    "--all",
    "--no-trunc",
    "--digests",
    "--format",
    _JSON_TEMPLATE,
)
_CONTAINER_COMMAND = (
    "docker",
    "container",
    "ls",
    "--all",
    "--no-trunc",
    "--size",
    "--format",
    _JSON_TEMPLATE,
)
_IMAGE_FIELDS = frozenset({"ID", "Repository", "Tag", "Digest", "CreatedAt", "Size"})
_CONTAINER_FIELDS = frozenset(
    {"ID", "Image", "Command", "CreatedAt", "State", "Status", "Size", "Names"}
)
_SIZE_PATTERN = re.compile(
    r"^(?P<number>\d+(?:\.\d+)?)\s*(?P<unit>B|kB|MB|GB|TB|PB|KiB|MiB|GiB|TiB|PiB)"
)
_SIZE_FACTORS = {
    "B": 1,
    "kB": 1000,
    "MB": 1000**2,
    "GB": 1000**3,
    "TB": 1000**4,
    "PB": 1000**5,
    "KiB": 1024,
    "MiB": 1024**2,
    "GiB": 1024**3,
    "TiB": 1024**4,
    "PiB": 1024**5,
}
_AI_TERMS = (
    "comfyui",
    "diffusion",
    "huggingface",
    "keras",
    "ollama",
    "llama",
    "pytorch",
    "stable-diffusion",
    "tensorflow",
    "text-generation",
    "vllm",
)


@dataclass(frozen=True, slots=True)
class DockerConfig:
    timeout: float = DEFAULT_TIMEOUT
    classify_ai: bool = False

    def __post_init__(self) -> None:
        if not math.isfinite(self.timeout) or self.timeout <= 0:
            raise ValueError("Docker timeout must be a finite number greater than zero")


class DockerProvider:
    name = "docker"

    def __init__(self, config: DockerConfig | None = None) -> None:
        self.config = config if config is not None else DockerConfig()

    def run(self, operation: Operation) -> ProviderResult:
        if operation is not Operation.LIST:
            raise UnsupportedOperationError(self.name, operation.value)

        image_output = self._invoke(_IMAGE_COMMAND, "image inventory")
        container_output = self._invoke(_CONTAINER_COMMAND, "container inventory")
        records = (
            *self._parse_records(image_output, "image", _IMAGE_FIELDS),
            *self._parse_records(container_output, "container", _CONTAINER_FIELDS),
        )
        return ProviderResult.success(self.name, operation, records)

    def _invoke(self, command: tuple[str, ...], inventory_name: str) -> str:
        try:
            completed = subprocess.run(
                command,
                check=False,
                capture_output=True,
                text=True,
                timeout=self.config.timeout,
            )
        except FileNotFoundError as error:
            raise ProviderUnavailableError(
                self.name, "Docker CLI is missing"
            ) from error
        except PermissionError as error:
            raise ProviderUnavailableError(
                self.name, "permission denied while executing the Docker CLI"
            ) from error
        except subprocess.TimeoutExpired as error:
            raise ProviderUnavailableError(
                self.name,
                f"{inventory_name} timed out after {self.config.timeout:g} seconds",
            ) from error
        except OSError as error:
            raise ProviderUnavailableError(
                self.name, f"cannot execute the Docker CLI: {error}"
            ) from error

        if completed.returncode != 0:
            diagnostic = completed.stderr.lower()
            if "permission denied" in diagnostic:
                raise ProviderUnavailableError(
                    self.name, "permission denied while accessing Docker"
                )
            if any(
                marker in diagnostic
                for marker in (
                    "cannot connect to the docker daemon",
                    "failed to connect to the docker api",
                    "error during connect",
                    "is the docker daemon running",
                    "docker daemon is not running",
                    "connection refused",
                )
            ):
                raise ProviderUnavailableError(
                    self.name, "Docker daemon is unavailable"
                )
            raise ProviderFailureError(
                self.name,
                Operation.LIST.value,
                f"{inventory_name} command exited with status {completed.returncode}",
            )
        return completed.stdout

    def _parse_records(
        self,
        output: str,
        kind: str,
        required_fields: frozenset[str],
    ) -> tuple[ModelRecord, ...]:
        records: list[ModelRecord] = []
        for line_number, line in enumerate(output.splitlines(), start=1):
            if not line.strip():
                self._malformed(kind, line_number, "blank JSON line")
            try:
                item = json.loads(line)
            except JSONDecodeError as error:
                self._malformed(kind, line_number, "invalid JSON")
            if not isinstance(item, dict):
                self._malformed(kind, line_number, "expected a JSON object")
            if any(
                not isinstance(key, str) or not isinstance(value, str)
                for key, value in item.items()
            ):
                self._malformed(kind, line_number, "all fields must be strings")
            missing = sorted(required_fields - item.keys())
            if missing:
                self._malformed(
                    kind,
                    line_number,
                    f"missing fields: {', '.join(missing)}",
                )
            identifier = item["ID"]
            if not identifier:
                self._malformed(kind, line_number, "ID must not be empty")

            attributes = {f"docker.{key}": value for key, value in item.items()}
            attributes["inventory.kind"] = kind
            if kind == "container":
                attributes["image.relationship"] = item["Image"]
                location = item["Names"] or None
            else:
                location = self._image_reference(item)
            if self.config.classify_ai:
                self._add_ai_heuristic(attributes, item)
            records.append(
                ModelRecord(
                    provider=self.name,
                    model_id=f"{kind}:{identifier}",
                    size_bytes=self._size_bytes(item["Size"], kind, line_number),
                    location=location,
                    attributes=attributes,
                )
            )
        return tuple(records)

    def _size_bytes(self, value: str, kind: str, line_number: int) -> int:
        match = _SIZE_PATTERN.match(value)
        if match is None:
            self._malformed(kind, line_number, "Size has an unsupported format")
        number = float(match.group("number"))
        return round(number * _SIZE_FACTORS[match.group("unit")])

    @staticmethod
    def _image_reference(item: dict[str, str]) -> str | None:
        repository = item["Repository"]
        tag = item["Tag"]
        if repository == "<none>":
            return None
        if tag == "<none>":
            return repository
        return f"{repository}:{tag}"

    @staticmethod
    def _add_ai_heuristic(
        attributes: dict[str, str], item: dict[str, str]
    ) -> None:
        searchable = " ".join(item.values()).lower()
        match = next((term for term in _AI_TERMS if term in searchable), None)
        attributes["heuristic.ai_related"] = "true" if match else "false"
        attributes["heuristic.classification"] = "optional"
        attributes["heuristic.match"] = match or "none"

    def _malformed(self, kind: str, line_number: int, reason: str) -> NoReturn:
        raise ProviderFailureError(
            self.name,
            Operation.LIST.value,
            f"malformed Docker {kind} output at line {line_number}: {reason}",
        )

"""Provider protocol and registry."""

from __future__ import annotations

from collections.abc import Iterable
from pathlib import Path
from typing import Protocol, runtime_checkable

from .docker import DockerConfig, DockerProvider
from .errors import UnsupportedProviderError
from .lm_studio import LMStudioConfig, LMStudioProvider
from .models import Operation, ProviderResult
from .ollama import OllamaConfig, OllamaProvider


@runtime_checkable
class Provider(Protocol):
    @property
    def name(self) -> str:
        """Return the stable command-line name for this provider."""

    def run(self, operation: Operation) -> ProviderResult:
        """Run a read-only provider operation."""


class ProviderRegistry:
    def __init__(
        self,
        providers: Iterable[Provider] = (),
        *,
        unsupported_names: Iterable[str] = (),
    ) -> None:
        self._providers: dict[str, Provider] = {}
        for provider in providers:
            if provider.name in self._providers:
                raise ValueError(f"Duplicate provider name: {provider.name!r}")
            self._providers[provider.name] = provider

        unsupported = set(unsupported_names)
        overlap = self._providers.keys() & unsupported
        if overlap:
            name = sorted(overlap)[0]
            raise ValueError(f"Provider cannot also be unsupported: {name!r}")
        self._unsupported_names = frozenset(unsupported)

    @property
    def names(self) -> tuple[str, ...]:
        return tuple(sorted((*self._providers, *self._unsupported_names)))

    def run(self, provider_name: str, operation: Operation) -> ProviderResult:
        provider = self._providers.get(provider_name)
        if provider is None:
            raise UnsupportedProviderError(provider_name)
        return provider.run(operation)


def create_default_registry(
    *,
    ollama_base_url: str | None = None,
    ollama_timeout: float | None = None,
    lm_studio_base_url: str | None = None,
    lm_studio_timeout: float | None = None,
    lm_studio_model_roots: tuple[str, ...] | None = None,
    docker_timeout: float | None = None,
    docker_classify_ai: bool = False,
) -> ProviderRegistry:
    ollama_defaults = OllamaConfig()
    ollama_config = OllamaConfig(
        base_url=ollama_base_url or ollama_defaults.base_url,
        timeout=(
            ollama_timeout if ollama_timeout is not None else ollama_defaults.timeout
        ),
    )
    lm_studio_defaults = LMStudioConfig()
    lm_studio_config = LMStudioConfig(
        base_url=lm_studio_base_url or lm_studio_defaults.base_url,
        timeout=(
            lm_studio_timeout
            if lm_studio_timeout is not None
            else lm_studio_defaults.timeout
        ),
        model_roots=(
            tuple(Path(root) for root in lm_studio_model_roots)
            if lm_studio_model_roots is not None
            else lm_studio_defaults.model_roots
        ),
    )
    docker_defaults = DockerConfig()
    docker_config = DockerConfig(
        timeout=(
            docker_timeout
            if docker_timeout is not None
            else docker_defaults.timeout
        ),
        classify_ai=docker_classify_ai,
    )
    return ProviderRegistry(
        (
            OllamaProvider(ollama_config),
            LMStudioProvider(lm_studio_config),
            DockerProvider(docker_config),
        ),
    )


DEFAULT_REGISTRY = create_default_registry()

"""Typed records shared by the command line and provider implementations."""

from __future__ import annotations

from dataclasses import dataclass, field
from enum import StrEnum
from types import MappingProxyType
from typing import Mapping


class Operation(StrEnum):
    LIST = "list"


class ProviderStatus(StrEnum):
    OK = "ok"
    UNAVAILABLE = "unavailable"
    UNSUPPORTED = "unsupported"
    ERROR = "error"


@dataclass(frozen=True, slots=True)
class ModelRecord:
    provider: str
    model_id: str
    size_bytes: int | None = None
    location: str | None = None
    attributes: Mapping[str, str] = field(default_factory=dict)

    def __post_init__(self) -> None:
        if not self.provider:
            raise ValueError("provider must not be empty")
        if not self.model_id:
            raise ValueError("model_id must not be empty")
        if self.size_bytes is not None and self.size_bytes < 0:
            raise ValueError("size_bytes must not be negative")
        normalized = dict(sorted(self.attributes.items()))
        if any(not isinstance(key, str) or not isinstance(value, str) for key, value in normalized.items()):
            raise TypeError("attribute keys and values must be strings")
        object.__setattr__(self, "attributes", MappingProxyType(normalized))

    def to_dict(self) -> dict[str, object]:
        return {
            "attributes": dict(self.attributes),
            "location": self.location,
            "model_id": self.model_id,
            "provider": self.provider,
            "size_bytes": self.size_bytes,
        }


@dataclass(frozen=True, slots=True)
class ProviderResult:
    provider: str
    operation: Operation
    status: ProviderStatus
    records: tuple[ModelRecord, ...] = ()
    message: str | None = None

    def __post_init__(self) -> None:
        if not self.provider:
            raise ValueError("provider must not be empty")
        if self.status is ProviderStatus.OK and self.message is not None:
            raise ValueError("successful results must not contain an error message")
        if self.status is not ProviderStatus.OK and not self.message:
            raise ValueError("unsuccessful results must contain an error message")
        if any(record.provider != self.provider for record in self.records):
            raise ValueError("record provider must match result provider")

    @classmethod
    def success(
        cls,
        provider: str,
        operation: Operation,
        records: tuple[ModelRecord, ...] = (),
    ) -> ProviderResult:
        ordered = tuple(
            sorted(records, key=lambda record: (record.model_id, record.location or ""))
        )
        return cls(provider, operation, ProviderStatus.OK, ordered)

    @classmethod
    def failure(
        cls,
        provider: str,
        operation: Operation,
        status: ProviderStatus,
        message: str,
        records: tuple[ModelRecord, ...] = (),
    ) -> ProviderResult:
        if status is ProviderStatus.OK:
            raise ValueError("failure status must not be ok")
        ordered = tuple(
            sorted(records, key=lambda record: (record.model_id, record.location or ""))
        )
        return cls(provider, operation, status, ordered, message)

    def to_dict(self) -> dict[str, object]:
        return {
            "message": self.message,
            "operation": self.operation.value,
            "provider": self.provider,
            "records": [record.to_dict() for record in self.records],
            "status": self.status.value,
        }

"""Command-line interface for model storage checks."""

from __future__ import annotations

import argparse
import json
import math
import sys
from collections.abc import Sequence
from typing import TextIO

from .docker import DEFAULT_TIMEOUT as DEFAULT_DOCKER_TIMEOUT
from .errors import (
    ProviderFailureError,
    ProviderUnavailableError,
    UnsupportedOperationError,
    UnsupportedProviderError,
)
from .lm_studio import (
    DEFAULT_BASE_URL as DEFAULT_LM_STUDIO_BASE_URL,
    DEFAULT_MODEL_ROOTS,
    DEFAULT_TIMEOUT as DEFAULT_LM_STUDIO_TIMEOUT,
    LMStudioConfig,
)
from .models import Operation, ProviderResult, ProviderStatus
from .ollama import DEFAULT_BASE_URL, DEFAULT_TIMEOUT, OllamaConfig
from .providers import DEFAULT_REGISTRY, ProviderRegistry, create_default_registry

EXIT_ERROR = 1
EXIT_USAGE = 2
EXIT_UNAVAILABLE = 3
EXIT_UNSUPPORTED = 4


def _positive_timeout(value: str) -> float:
    try:
        timeout = float(value)
    except ValueError as error:
        raise argparse.ArgumentTypeError("must be a number") from error
    if not math.isfinite(timeout) or timeout <= 0:
        raise argparse.ArgumentTypeError(
            "must be a finite number greater than zero"
        )
    return timeout


def _ollama_base_url(value: str) -> str:
    try:
        return OllamaConfig(base_url=value).base_url
    except ValueError as error:
        raise argparse.ArgumentTypeError(str(error)) from error


def _lm_studio_base_url(value: str) -> str:
    try:
        return LMStudioConfig(base_url=value).base_url
    except ValueError as error:
        raise argparse.ArgumentTypeError(str(error)) from error


def build_parser(registry: ProviderRegistry = DEFAULT_REGISTRY) -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="model-storage-checker",
        description="Report locally stored models from read-only providers.",
    )
    parser.add_argument(
        "operation",
        choices=tuple(operation.value for operation in Operation),
        help="read-only operation to perform",
    )
    parser.add_argument(
        "--provider",
        action="append",
        choices=registry.names,
        dest="providers",
        help="provider to check; repeat to select multiple (default: all)",
    )
    parser.add_argument(
        "--output",
        choices=("text", "json"),
        default="text",
        help="output format (default: text)",
    )
    parser.add_argument(
        "--ollama-base-url",
        default=DEFAULT_BASE_URL,
        type=_ollama_base_url,
        help=f"Ollama service base URL (default: {DEFAULT_BASE_URL})",
    )
    parser.add_argument(
        "--ollama-timeout",
        default=DEFAULT_TIMEOUT,
        type=_positive_timeout,
        metavar="SECONDS",
        help=f"Ollama request timeout in seconds (default: {DEFAULT_TIMEOUT:g})",
    )
    parser.add_argument(
        "--lm-studio-base-url",
        default=DEFAULT_LM_STUDIO_BASE_URL,
        type=_lm_studio_base_url,
        help=(
            "LM Studio OpenAI-compatible base URL "
            f"(default: {DEFAULT_LM_STUDIO_BASE_URL})"
        ),
    )
    parser.add_argument(
        "--lm-studio-timeout",
        default=DEFAULT_LM_STUDIO_TIMEOUT,
        type=_positive_timeout,
        metavar="SECONDS",
        help=(
            "LM Studio request timeout in seconds "
            f"(default: {DEFAULT_LM_STUDIO_TIMEOUT:g})"
        ),
    )
    parser.add_argument(
        "--lm-studio-model-root",
        action="append",
        dest="lm_studio_model_roots",
        metavar="PATH",
        help=(
            "LM Studio model root to scan recursively; repeat for multiple roots "
            f"(default: {DEFAULT_MODEL_ROOTS[0]})"
        ),
    )
    parser.add_argument(
        "--docker-timeout",
        default=DEFAULT_DOCKER_TIMEOUT,
        type=_positive_timeout,
        metavar="SECONDS",
        help=(
            "Docker CLI timeout per inventory command in seconds "
            f"(default: {DEFAULT_DOCKER_TIMEOUT:g})"
        ),
    )
    parser.add_argument(
        "--docker-ai-heuristic",
        action="store_true",
        help="annotate Docker records with an optional AI-related heuristic",
    )
    return parser


def _failure_result(
    provider: str, operation: Operation, error: Exception
) -> ProviderResult:
    if isinstance(error, ProviderUnavailableError):
        status = ProviderStatus.UNAVAILABLE
    elif isinstance(error, (UnsupportedProviderError, UnsupportedOperationError)):
        status = ProviderStatus.UNSUPPORTED
    else:
        status = ProviderStatus.ERROR
    return ProviderResult.failure(provider, operation, status, str(error))


def collect_results(
    registry: ProviderRegistry,
    provider_names: Sequence[str],
    operation: Operation,
) -> tuple[ProviderResult, ...]:
    results: list[ProviderResult] = []
    for provider_name in sorted(set(provider_names)):
        try:
            result = registry.run(provider_name, operation)
        except (
            ProviderFailureError,
            ProviderUnavailableError,
            UnsupportedOperationError,
            UnsupportedProviderError,
        ) as error:
            result = _failure_result(provider_name, operation, error)
        results.append(result)
    return tuple(results)


def _write_json(
    stream: TextIO, operation: Operation, results: Sequence[ProviderResult]
) -> None:
    payload = {
        "operation": operation.value,
        "providers": [result.to_dict() for result in results],
        "version": 1,
    }
    json.dump(payload, stream, ensure_ascii=True, indent=2, sort_keys=True)
    stream.write("\n")


def _write_text(stream: TextIO, results: Sequence[ProviderResult]) -> None:
    for result in results:
        if result.status is ProviderStatus.OK:
            noun = "inventory records" if result.provider == "docker" else "models"
            stream.write(f"{result.provider}: ok ({len(result.records)} {noun})\n")
        else:
            noun = "inventory records" if result.provider == "docker" else "models"
            count = f" ({len(result.records)} {noun})" if result.records else ""
            stream.write(
                f"{result.provider}: {result.status.value}{count} - {result.message}\n"
            )
        for record in result.records:
            size = (
                f"{record.size_bytes} bytes"
                if record.size_bytes is not None
                else "size unknown"
            )
            stream.write(f"  {record.model_id} ({size})\n")


def _exit_code(results: Sequence[ProviderResult]) -> int:
    statuses = {result.status for result in results}
    if ProviderStatus.ERROR in statuses:
        return EXIT_ERROR
    if ProviderStatus.UNSUPPORTED in statuses:
        return EXIT_UNSUPPORTED
    if ProviderStatus.UNAVAILABLE in statuses:
        return EXIT_UNAVAILABLE
    return 0


def main(
    argv: Sequence[str] | None = None,
    *,
    registry: ProviderRegistry = DEFAULT_REGISTRY,
    stdout: TextIO | None = None,
) -> int:
    args = build_parser(registry).parse_args(argv)
    stream = stdout if stdout is not None else sys.stdout
    operation = Operation(args.operation)
    active_registry = registry
    if registry is DEFAULT_REGISTRY:
        active_registry = create_default_registry(
            ollama_base_url=args.ollama_base_url,
            ollama_timeout=args.ollama_timeout,
            lm_studio_base_url=args.lm_studio_base_url,
            lm_studio_timeout=args.lm_studio_timeout,
            lm_studio_model_roots=(
                tuple(args.lm_studio_model_roots)
                if args.lm_studio_model_roots is not None
                else None
            ),
            docker_timeout=args.docker_timeout,
            docker_classify_ai=args.docker_ai_heuristic,
        )
    provider_names = (
        args.providers if args.providers is not None else active_registry.names
    )
    results = collect_results(active_registry, provider_names, operation)

    if args.output == "json":
        _write_json(stream, operation, results)
    else:
        _write_text(stream, results)
    return _exit_code(results)

"""Read-only Docker image and container inventory via the Docker CLI."""

from __future__ import annotations

import json
import math
import re
import subprocess
from dataclasses import dataclass
from json import JSONDecodeError
from typing import NoReturn

from .errors import (
    ProviderFailureError,
    ProviderUnavailableError,
    UnsupportedOperationError,
)
from .models import ModelRecord, Operation, ProviderResult

DEFAULT_TIMEOUT = 10.0
_JSON_TEMPLATE = "{{json .}}"
_IMAGE_COMMAND = (
    "docker",
    "image",
    "ls",
    "--all",
    "--no-trunc",
    "--digests",
    "--format",
    _JSON_TEMPLATE,
)
_CONTAINER_COMMAND = (
    "docker",
    "container",
    "ls",
    "--all",
    "--no-trunc",
    "--size",
    "--format",
    _JSON_TEMPLATE,
)
_IMAGE_FIELDS = frozenset({"ID", "Repository", "Tag", "Digest", "CreatedAt", "Size"})
_CONTAINER_FIELDS = frozenset(
    {"ID", "Image", "Command", "CreatedAt", "State", "Status", "Size", "Names"}
)
_SIZE_PATTERN = re.compile(
    r"^(?P<number>\d+(?:\.\d+)?)\s*(?P<unit>B|kB|MB|GB|TB|PB|KiB|MiB|GiB|TiB|PiB)"
)
_SIZE_FACTORS = {
    "B": 1,
    "kB": 1000,
    "MB": 1000**2,
    "GB": 1000**3,
    "TB": 1000**4,
    "PB": 1000**5,
    "KiB": 1024,
    "MiB": 1024**2,
    "GiB": 1024**3,
    "TiB": 1024**4,
    "PiB": 1024**5,
}
_AI_TERMS = (
    "comfyui",
    "diffusion",
    "huggingface",
    "keras",
    "ollama",
    "llama",
    "pytorch",
    "stable-diffusion",
    "tensorflow",
    "text-generation",
    "vllm",
)


@dataclass(frozen=True, slots=True)
class DockerConfig:
    timeout: float = DEFAULT_TIMEOUT
    classify_ai: bool = False

    def __post_init__(self) -> None:
        if not math.isfinite(self.timeout) or self.timeout <= 0:
            raise ValueError("Docker timeout must be a finite number greater than zero")


class DockerProvider:
    name = "docker"

    def __init__(self, config: DockerConfig | None = None) -> None:
        self.config = config if config is not None else DockerConfig()

    def run(self, operation: Operation) -> ProviderResult:
        if operation is not Operation.LIST:
            raise UnsupportedOperationError(self.name, operation.value)

        image_output = self._invoke(_IMAGE_COMMAND, "image inventory")
        container_output = self._invoke(_CONTAINER_COMMAND, "container inventory")
        records = (
            *self._parse_records(image_output, "image", _IMAGE_FIELDS),
            *self._parse_records(container_output, "container", _CONTAINER_FIELDS),
        )
        return ProviderResult.success(self.name, operation, records)

    def _invoke(self, command: tuple[str, ...], inventory_name: str) -> str:
        try:
            completed = subprocess.run(
                command,
                check=False,
                capture_output=True,
                text=True,
                timeout=self.config.timeout,
            )
        except FileNotFoundError as error:
            raise ProviderUnavailableError(
                self.name, "Docker CLI is missing"
            ) from error
        except PermissionError as error:
            raise ProviderUnavailableError(
                self.name, "permission denied while executing the Docker CLI"
            ) from error
        except subprocess.TimeoutExpired as error:
            raise ProviderUnavailableError(
                self.name,
                f"{inventory_name} timed out after {self.config.timeout:g} seconds",
            ) from error
        except OSError as error:
            raise ProviderUnavailableError(
                self.name, f"cannot execute the Docker CLI: {error}"
            ) from error

        if completed.returncode != 0:
            diagnostic = completed.stderr.lower()
            if "permission denied" in diagnostic:
                raise ProviderUnavailableError(
                    self.name, "permission denied while accessing Docker"
                )
            if any(
                marker in diagnostic
                for marker in (
                    "cannot connect to the docker daemon",
                    "failed to connect to the docker api",
                    "error during connect",
                    "is the docker daemon running",
                    "docker daemon is not running",
                    "connection refused",
                )
            ):
                raise ProviderUnavailableError(
                    self.name, "Docker daemon is unavailable"
                )
            raise ProviderFailureError(
                self.name,
                Operation.LIST.value,
                f"{inventory_name} command exited with status {completed.returncode}",
            )
        return completed.stdout

    def _parse_records(
        self,
        output: str,
        kind: str,
        required_fields: frozenset[str],
    ) -> tuple[ModelRecord, ...]:
        records: list[ModelRecord] = []
        for line_number, line in enumerate(output.splitlines(), start=1):
            if not line.strip():
                self._malformed(kind, line_number, "blank JSON line")
            try:
                item = json.loads(line)
            except JSONDecodeError as error:
                self._malformed(kind, line_number, "invalid JSON")
            if not isinstance(item, dict):
                self._malformed(kind, line_number, "expected a JSON object")
            if any(
                not isinstance(key, str) or not isinstance(value, str)
                for key, value in item.items()
            ):
                self._malformed(kind, line_number, "all fields must be strings")
            missing = sorted(required_fields - item.keys())
            if missing:
                self._malformed(
                    kind,
                    line_number,
                    f"missing fields: {', '.join(missing)}",
                )
            identifier = item["ID"]
            if not identifier:
                self._malformed(kind, line_number, "ID must not be empty")

            attributes = {f"docker.{key}": value for key, value in item.items()}
            attributes["inventory.kind"] = kind
            if kind == "container":
                attributes["image.relationship"] = item["Image"]
                location = item["Names"] or None
            else:
                location = self._image_reference(item)
            if self.config.classify_ai:
                self._add_ai_heuristic(attributes, item)
            records.append(
                ModelRecord(
                    provider=self.name,
                    model_id=f"{kind}:{identifier}",
                    size_bytes=self._size_bytes(item["Size"], kind, line_number),
                    location=location,
                    attributes=attributes,
                )
            )
        return tuple(records)

    def _size_bytes(self, value: str, kind: str, line_number: int) -> int:
        match = _SIZE_PATTERN.match(value)
        if match is None:
            self._malformed(kind, line_number, "Size has an unsupported format")
        number = float(match.group("number"))
        return round(number * _SIZE_FACTORS[match.group("unit")])

    @staticmethod
    def _image_reference(item: dict[str, str]) -> str | None:
        repository = item["Repository"]
        tag = item["Tag"]
        if repository == "<none>":
            return None
        if tag == "<none>":
            return repository
        return f"{repository}:{tag}"

    @staticmethod
    def _add_ai_heuristic(
        attributes: dict[str, str], item: dict[str, str]
    ) -> None:
        searchable = " ".join(item.values()).lower()
        match = next((term for term in _AI_TERMS if term in searchable), None)
        attributes["heuristic.ai_related"] = "true" if match else "false"
        attributes["heuristic.classification"] = "optional"
        attributes["heuristic.match"] = match or "none"

    def _malformed(self, kind: str, line_number: int, reason: str) -> NoReturn:
        raise ProviderFailureError(
            self.name,
            Operation.LIST.value,
            f"malformed Docker {kind} output at line {line_number}: {reason}",
        )

"""Read-only inventory provider for a local Ollama service."""

from __future__ import annotations

import json
import math
import socket
from dataclasses import dataclass
from json import JSONDecodeError
from typing import Any, NoReturn
from urllib.error import URLError
from urllib.parse import urlsplit
from urllib.request import Request, urlopen

from .errors import (
    ProviderFailureError,
    ProviderUnavailableError,
    UnsupportedOperationError,
)
from .models import ModelRecord, Operation, ProviderResult

DEFAULT_BASE_URL = "http://127.0.0.1:11434"
DEFAULT_TIMEOUT = 5.0


@dataclass(frozen=True, slots=True)
class OllamaConfig:
    base_url: str = DEFAULT_BASE_URL
    timeout: float = DEFAULT_TIMEOUT

    def __post_init__(self) -> None:
        normalized_url = self.base_url.rstrip("/")
        parsed = urlsplit(normalized_url)
        if parsed.scheme not in {"http", "https"} or not parsed.netloc:
            raise ValueError("Ollama base URL must be an absolute HTTP(S) URL")
        if parsed.query or parsed.fragment:
            raise ValueError("Ollama base URL must not include a query or fragment")
        if not math.isfinite(self.timeout) or self.timeout <= 0:
            raise ValueError("Ollama timeout must be a finite number greater than zero")
        object.__setattr__(self, "base_url", normalized_url)


class OllamaProvider:
    name = "ollama"

    def __init__(self, config: OllamaConfig | None = None) -> None:
        self.config = config if config is not None else OllamaConfig()

    def run(self, operation: Operation) -> ProviderResult:
        if operation is not Operation.LIST:
            raise UnsupportedOperationError(self.name, operation.value)

        payload = self._fetch_tags()
        records = self._parse_records(payload, operation)
        return ProviderResult.success(self.name, operation, tuple(records))

    def _fetch_tags(self) -> object:
        endpoint = f"{self.config.base_url}/api/tags"
        request = Request(
            endpoint,
            headers={"Accept": "application/json"},
            method="GET",
        )
        try:
            with urlopen(request, timeout=self.config.timeout) as response:
                body = response.read()
        except (URLError, TimeoutError, socket.timeout, OSError) as error:
            reason = getattr(error, "reason", error)
            raise ProviderUnavailableError(
                self.name, f"cannot reach {endpoint}: {reason}"
            ) from error

        try:
            return json.loads(body)
        except (JSONDecodeError, UnicodeDecodeError) as error:
            raise ProviderFailureError(
                self.name, Operation.LIST.value, "response is not valid JSON"
            ) from error

    def _parse_records(
        self, payload: object, operation: Operation
    ) -> list[ModelRecord]:
        if not isinstance(payload, dict) or "models" not in payload:
            self._malformed(operation, "expected an object containing 'models'")
        models = payload["models"]
        if not isinstance(models, list):
            self._malformed(operation, "'models' must be an array")

        records: list[ModelRecord] = []
        for index, model in enumerate(models):
            if not isinstance(model, dict):
                self._malformed(operation, f"models[{index}] must be an object")
            records.append(self._record_from_model(model, index, operation))
        return records

    def _record_from_model(
        self, model: dict[str, Any], index: int, operation: Operation
    ) -> ModelRecord:
        name = model.get("name")
        if not isinstance(name, str) or not name:
            self._malformed(
                operation, f"models[{index}].name must be a non-empty string"
            )

        size = model.get("size")
        if not isinstance(size, int) or isinstance(size, bool) or size < 0:
            self._malformed(
                operation, f"models[{index}].size must be a non-negative integer"
            )

        attributes: dict[str, str] = {}
        self._copy_string(model, "digest", attributes, index, operation)
        self._copy_string(model, "modified_at", attributes, index, operation)

        details = model.get("details")
        if details is not None:
            if not isinstance(details, dict):
                self._malformed(operation, f"models[{index}].details must be an object")
            for key in (
                "family",
                "format",
                "parameter_size",
                "quantization_level",
            ):
                self._copy_string(
                    details, key, attributes, index, operation, prefix="details."
                )

        return ModelRecord(
            provider=self.name,
            model_id=name,
            size_bytes=size,
            attributes=attributes,
        )

    def _copy_string(
        self,
        source: dict[str, Any],
        key: str,
        target: dict[str, str],
        index: int,
        operation: Operation,
        *,
        prefix: str = "",
    ) -> None:
        value = source.get(key)
        if value is None:
            return
        if not isinstance(value, str):
            self._malformed(
                operation, f"models[{index}].{prefix}{key} must be a string"
            )
        target[key] = value

    def _malformed(self, operation: Operation, reason: str) -> NoReturn:
        raise ProviderFailureError(
            self.name, operation.value, f"malformed response: {reason}"
        )

"""Read-only inventory provider for LM Studio APIs and model storage."""

from __future__ import annotations

import json
import math
import os
import socket
from collections import defaultdict
from dataclasses import dataclass
from json import JSONDecodeError
from pathlib import Path
from typing import Any, NoReturn
from urllib.error import URLError
from urllib.parse import urlsplit
from urllib.request import Request, urlopen

from .errors import (
    ProviderFailureError,
    ProviderUnavailableError,
    UnsupportedOperationError,
)
from .models import ModelRecord, Operation, ProviderResult, ProviderStatus

DEFAULT_BASE_URL = "http://127.0.0.1:1234/v1"
DEFAULT_TIMEOUT = 5.0
DEFAULT_MODEL_ROOTS = (Path.home() / ".lmstudio" / "models",)
MODEL_FILE_SUFFIXES = frozenset(
    {".bin", ".gguf", ".mlx", ".onnx", ".pt", ".pth", ".safetensors"}
)


@dataclass(frozen=True, slots=True)
class LMStudioConfig:
    base_url: str = DEFAULT_BASE_URL
    timeout: float = DEFAULT_TIMEOUT
    model_roots: tuple[Path, ...] = DEFAULT_MODEL_ROOTS

    def __post_init__(self) -> None:
        normalized_url = self.base_url.rstrip("/")
        parsed = urlsplit(normalized_url)
        if parsed.scheme not in {"http", "https"} or not parsed.netloc:
            raise ValueError("LM Studio base URL must be an absolute HTTP(S) URL")
        if parsed.query or parsed.fragment:
            raise ValueError("LM Studio base URL must not include a query or fragment")
        if not math.isfinite(self.timeout) or self.timeout <= 0:
            raise ValueError("LM Studio timeout must be a finite number greater than zero")

        roots: list[Path] = []
        for root in self.model_roots:
            path = Path(root).expanduser().resolve(strict=False)
            if path not in roots:
                roots.append(path)
        object.__setattr__(self, "base_url", normalized_url)
        object.__setattr__(self, "model_roots", tuple(roots))


class LMStudioProvider:
    name = "lm-studio"

    def __init__(self, config: LMStudioConfig | None = None) -> None:
        self.config = config if config is not None else LMStudioConfig()

    def run(self, operation: Operation) -> ProviderResult:
        if operation is not Operation.LIST:
            raise UnsupportedOperationError(self.name, operation.value)

        api_records: list[ModelRecord] = []
        file_records: list[ModelRecord] = []
        issues: list[tuple[ProviderStatus, str]] = []

        try:
            api_records = self._parse_api_records(self._fetch_models(), operation)
        except ProviderUnavailableError as error:
            issues.append(
                (ProviderStatus.UNAVAILABLE, f"API discovery failed: {error.reason}")
            )
        except ProviderFailureError as error:
            issues.append((ProviderStatus.ERROR, f"API discovery failed: {error.reason}"))

        file_records, file_errors = self._discover_files()
        issues.extend(
            (ProviderStatus.ERROR, f"filesystem discovery failed: {error}")
            for error in file_errors
        )

        records = tuple(self._deduplicate(api_records, file_records))
        if not issues:
            return ProviderResult.success(self.name, operation, records)

        status = (
            ProviderStatus.ERROR
            if any(item_status is ProviderStatus.ERROR for item_status, _ in issues)
            else ProviderStatus.UNAVAILABLE
        )
        return ProviderResult.failure(
            self.name,
            operation,
            status,
            "; ".join(message for _, message in issues),
            records,
        )

    def _fetch_models(self) -> object:
        endpoint = f"{self.config.base_url}/models"
        request = Request(
            endpoint,
            headers={"Accept": "application/json"},
            method="GET",
        )
        try:
            with urlopen(request, timeout=self.config.timeout) as response:
                body = response.read()
        except (URLError, TimeoutError, socket.timeout, OSError) as error:
            reason = getattr(error, "reason", error)
            raise ProviderUnavailableError(
                self.name, f"cannot reach {endpoint}: {reason}"
            ) from error

        try:
            return json.loads(body)
        except (JSONDecodeError, UnicodeDecodeError) as error:
            raise ProviderFailureError(
                self.name, Operation.LIST.value, "response is not valid JSON"
            ) from error

    def _parse_api_records(
        self, payload: object, operation: Operation
    ) -> list[ModelRecord]:
        if not isinstance(payload, dict) or "data" not in payload:
            self._malformed(operation, "expected an object containing 'data'")
        models = payload["data"]
        if not isinstance(models, list):
            self._malformed(operation, "'data' must be an array")

        records: list[ModelRecord] = []
        for index, model in enumerate(models):
            if not isinstance(model, dict):
                self._malformed(operation, f"data[{index}] must be an object")
            model_id = model.get("id")
            if not isinstance(model_id, str) or not model_id:
                self._malformed(
                    operation, f"data[{index}].id must be a non-empty string"
                )

            attributes = {"source": "api"}
            for key in ("object", "owned_by"):
                value = model.get(key)
                if value is not None:
                    if not isinstance(value, str):
                        self._malformed(
                            operation, f"data[{index}].{key} must be a string"
                        )
                    attributes[f"api.{key}"] = value
            created = model.get("created")
            if created is not None:
                if (
                    not isinstance(created, int)
                    or isinstance(created, bool)
                    or created < 0
                ):
                    self._malformed(
                        operation,
                        f"data[{index}].created must be a non-negative integer",
                    )
                attributes["api.created"] = str(created)

            records.append(
                ModelRecord(
                    provider=self.name,
                    model_id=model_id,
                    attributes=attributes,
                )
            )
        return records

    def _discover_files(self) -> tuple[list[ModelRecord], list[str]]:
        records: list[ModelRecord] = []
        errors: list[str] = []
        for root in self.config.model_roots:
            try:
                if not root.exists():
                    raise FileNotFoundError("root does not exist")
                if not root.is_dir():
                    raise NotADirectoryError("root is not a directory")
            except OSError as error:
                errors.append(f"{root}: {error}")
                continue

            walk_errors: list[OSError] = []
            for directory, directory_names, file_names in os.walk(
                root, onerror=walk_errors.append
            ):
                directory_names.sort()
                for file_name in sorted(file_names):
                    path = Path(directory, file_name)
                    if path.suffix.lower() not in MODEL_FILE_SUFFIXES:
                        continue
                    try:
                        if not path.is_file():
                            continue
                        size = path.stat().st_size
                    except OSError as error:
                        errors.append(f"{path}: {error}")
                        continue
                    relative_path = path.relative_to(root)
                    model_id = relative_path.with_suffix("").as_posix()
                    records.append(
                        ModelRecord(
                            provider=self.name,
                            model_id=model_id,
                            size_bytes=size,
                            location=str(path),
                            attributes={
                                "filesystem.extension": path.suffix.lower(),
                                "filesystem.relative_path": relative_path.as_posix(),
                                "filesystem.root": str(root),
                                "source": "filesystem",
                            },
                        )
                    )
            errors.extend(
                f"{Path(error.filename) if error.filename else root}: {error}"
                for error in walk_errors
            )
        return records, errors

    def _deduplicate(
        self,
        api_records: list[ModelRecord],
        file_records: list[ModelRecord],
    ) -> list[ModelRecord]:
        api_by_id: dict[str, list[ModelRecord]] = defaultdict(list)
        for record in api_records:
            api_by_id[record.model_id].append(record)

        merged_api = {
            model_id: self._merge_api_records(records)
            for model_id, records in api_by_id.items()
        }
        matched_ids: set[str] = set()
        output: list[ModelRecord] = []
        seen_files: set[tuple[str, str | None]] = set()
        for record in sorted(
            file_records, key=lambda item: (item.model_id, item.location or "")
        ):
            file_key = (record.model_id, record.location)
            if file_key in seen_files:
                continue
            seen_files.add(file_key)
            api_record = merged_api.get(record.model_id)
            if api_record is None:
                output.append(record)
                continue
            matched_ids.add(record.model_id)
            attributes = dict(api_record.attributes)
            attributes.update(record.attributes)
            attributes["source"] = "api,filesystem"
            output.append(
                ModelRecord(
                    provider=self.name,
                    model_id=record.model_id,
                    size_bytes=record.size_bytes,
                    location=record.location,
                    attributes=attributes,
                )
            )

        output.extend(
            record
            for model_id, record in sorted(merged_api.items())
            if model_id not in matched_ids
        )
        return output

    def _merge_api_records(self, records: list[ModelRecord]) -> ModelRecord:
        model_id = records[0].model_id
        values: dict[str, set[str]] = defaultdict(set)
        for record in records:
            for key, value in record.attributes.items():
                values[key].add(value)
        attributes = {
            key: (
                next(iter(items))
                if len(items) == 1
                else json.dumps(sorted(items), separators=(",", ":"))
            )
            for key, items in values.items()
        }
        return ModelRecord(
            provider=self.name,
            model_id=model_id,
            attributes=attributes,
        )

    def _malformed(self, operation: Operation, reason: str) -> NoReturn:
        raise ProviderFailureError(
            self.name, operation.value, f"malformed response: {reason}"
        )

"""Deterministic unified summaries and advisory cleanup candidates."""

from __future__ import annotations

from dataclasses import dataclass
from types import MappingProxyType
from collections.abc import Iterable, Mapping, Sequence

from .models import ModelRecord, ProviderResult


@dataclass(frozen=True, slots=True)
class StorageTotal:
    record_count: int
    known_size_count: int
    unknown_size_count: int
    known_size_bytes: int

    @property
    def total_size_bytes(self) -> int | None:
        if self.unknown_size_count:
            return None
        return self.known_size_bytes

    def to_dict(self) -> dict[str, int | None]:
        return {
            "known_size_bytes": self.known_size_bytes,
            "known_size_count": self.known_size_count,
            "record_count": self.record_count,
            "total_size_bytes": self.total_size_bytes,
            "unknown_size_count": self.unknown_size_count,
        }


@dataclass(frozen=True, slots=True)
class CleanupCandidate:
    provider: str
    resource_type: str
    record_id: str
    rule: str
    rationale: str
    evidence: Mapping[str, str]

    def __post_init__(self) -> None:
        object.__setattr__(
            self, "evidence", MappingProxyType(dict(sorted(self.evidence.items())))
        )

    def to_dict(self) -> dict[str, object]:
        return {
            "advisory_only": True,
            "classification": "heuristic",
            "evidence": dict(self.evidence),
            "evidence_kind": "reported_metadata",
            "provider": self.provider,
            "rationale": self.rationale,
            "record_id": self.record_id,
            "resource_type": self.resource_type,
            "rule": self.rule,
        }


@dataclass(frozen=True, slots=True)
class StorageSummary:
    total: StorageTotal
    by_provider: Mapping[str, StorageTotal]
    by_resource_type: Mapping[str, StorageTotal]
    by_provider_and_resource_type: Mapping[str, Mapping[str, StorageTotal]]

    def to_dict(self) -> dict[str, object]:
        return {
            "by_provider": {
                provider: total.to_dict()
                for provider, total in self.by_provider.items()
            },
            "by_provider_and_resource_type": {
                provider: {
                    resource_type: total.to_dict()
                    for resource_type, total in resource_totals.items()
                }
                for provider, resource_totals in (
                    self.by_provider_and_resource_type.items()
                )
            },
            "by_resource_type": {
                resource_type: total.to_dict()
                for resource_type, total in self.by_resource_type.items()
            },
            "total": self.total.to_dict(),
        }


def resource_type(record: ModelRecord) -> str:
    kind = record.attributes.get("inventory.kind")
    if record.provider == "docker" and kind in {"container", "image"}:
        return kind
    return "model"


def build_summary(results: Sequence[ProviderResult]) -> StorageSummary:
    records = tuple(record for result in results for record in result.records)
    provider_names = sorted({result.provider for result in results})
    resource_types = sorted({resource_type(record) for record in records})

    by_provider = {
        provider: _total(
            record for record in records if record.provider == provider
        )
        for provider in provider_names
    }
    by_resource_type = {
        kind: _total(record for record in records if resource_type(record) == kind)
        for kind in resource_types
    }
    by_provider_and_resource_type = {
        provider: MappingProxyType(
            {
                kind: _total(
                    record
                    for record in records
                    if record.provider == provider and resource_type(record) == kind
                )
                for kind in sorted(
                    {
                        resource_type(record)
                        for record in records
                        if record.provider == provider
                    }
                )
            }
        )
        for provider in provider_names
    }
    return StorageSummary(
        total=_total(iter(records)),
        by_provider=MappingProxyType(by_provider),
        by_resource_type=MappingProxyType(by_resource_type),
        by_provider_and_resource_type=MappingProxyType(
            by_provider_and_resource_type
        ),
    )


def find_cleanup_candidates(
    results: Sequence[ProviderResult],
) -> tuple[CleanupCandidate, ...]:
    candidates: list[CleanupCandidate] = []
    for result in results:
        for record in result.records:
            kind = resource_type(record)
            if record.provider != "docker":
                continue
            if (
                kind == "image"
                and record.attributes.get("docker.Repository") == "<none>"
                and record.attributes.get("docker.Tag") == "<none>"
            ):
                candidates.append(
                    CleanupCandidate(
                        provider="docker",
                        resource_type="image",
                        record_id=record.model_id,
                        rule="docker-image-untagged",
                        rationale=(
                            "Repository and tag are both reported as <none>; "
                            "review whether the image is still needed. This does "
                            "not prove that removal is safe."
                        ),
                        evidence={
                            "docker.Repository": "<none>",
                            "docker.Tag": "<none>",
                        },
                    )
                )
            elif (
                kind == "container"
                and record.attributes.get("docker.State", "").lower()
                in {"dead", "exited"}
            ):
                state = record.attributes["docker.State"]
                candidates.append(
                    CleanupCandidate(
                        provider="docker",
                        resource_type="container",
                        record_id=record.model_id,
                        rule="docker-container-not-running",
                        rationale=(
                            "State is reported as exited or dead; review whether "
                            "the container is still needed. State alone does not "
                            "prove that removal is safe."
                        ),
                        evidence={"docker.State": state},
                    )
                )
    return tuple(
        sorted(
            candidates,
            key=lambda item: (
                item.provider,
                item.resource_type,
                item.record_id,
                item.rule,
            ),
        )
    )


def _total(records: Iterable[ModelRecord]) -> StorageTotal:
    materialized = tuple(records)
    known_sizes = tuple(
        record.size_bytes
        for record in materialized
        if record.size_bytes is not None
    )
    return StorageTotal(
        record_count=len(materialized),
        known_size_count=len(known_sizes),
        unknown_size_count=len(materialized) - len(known_sizes),
        known_size_bytes=sum(known_sizes),
    )

def _write_json(
    stream: TextIO, operation: Operation, results: Sequence[ProviderResult]
) -> None:
    summary = build_summary(results)
    candidates = find_cleanup_candidates(results)
    payload = {
        "cleanup_candidates": [candidate.to_dict() for candidate in candidates],
        "operation": operation.value,
        "providers": [result.to_dict() for result in results],
        "storage_summary": summary.to_dict(),
        "version": 2,
    }
    json.dump(payload, stream, ensure_ascii=True, indent=2, sort_keys=True)
    stream.write("\n")


def _write_text(stream: TextIO, results: Sequence[ProviderResult]) -> None:
    for result in results:
        if result.status is ProviderStatus.OK:
            noun = "inventory records" if result.provider == "docker" else "models"
            stream.write(f"{result.provider}: ok ({len(result.records)} {noun})\n")
        else:
            noun = "inventory records" if result.provider == "docker" else "models"
            count = f" ({len(result.records)} {noun})" if result.records else ""
            stream.write(
                f"{result.provider}: {result.status.value}{count} - {result.message}\n"
            )
        for record in result.records:
            size = (
                f"{record.size_bytes} bytes"
                if record.size_bytes is not None
                else "size unknown"
            )
            stream.write(f"  {record.model_id} ({size})\n")

    summary = build_summary(results)
    stream.write("storage summary:\n")
    stream.write(f"  all: {_format_total(summary.total)}\n")
    for provider, total in summary.by_provider.items():
        stream.write(f"  provider {provider}: {_format_total(total)}\n")
        for resource_type, resource_total in (
            summary.by_provider_and_resource_type[provider].items()
        ):
            stream.write(
                f"    {resource_type}: {_format_total(resource_total)}\n"
            )

    candidates = find_cleanup_candidates(results)
    stream.write(f"cleanup candidates (advisory only): {len(candidates)}\n")
    for candidate in candidates:
        evidence = ", ".join(
            f"{key}={value}" for key, value in candidate.evidence.items()
        )
        stream.write(
            f"  {candidate.provider}/{candidate.resource_type}/"
            f"{candidate.record_id}: heuristic {candidate.rule}\n"
            f"    evidence (reported metadata): {evidence}\n"
            f"    advisory: {candidate.rationale}\n"
        )


def _format_total(total: StorageTotal) -> str:
    known_size_bytes = total.known_size_bytes
    unknown_size_count = total.unknown_size_count
    record_count = total.record_count
    if unknown_size_count:
        size = (
            f"{known_size_bytes} known bytes; "
            f"{unknown_size_count} record(s) have unknown size"
        )
    else:
        size = f"{known_size_bytes} bytes"
    return f"{record_count} record(s), {size}"


def _exit_code(results: Sequence[ProviderResult]) -> int:
    statuses = {result.status for result in results}
    if ProviderStatus.ERROR in statuses:
        return EXIT_ERROR
    if ProviderStatus.UNSUPPORTED in statuses:
        return EXIT_UNSUPPORTED
    if ProviderStatus.UNAVAILABLE in statuses:
        return EXIT_UNAVAILABLE
    return 0


def main(
    argv: Sequence[str] | None = None,
    *,
    registry: ProviderRegistry = DEFAULT_REGISTRY,
    stdout: TextIO | None = None,
) -> int:
    args = build_parser(registry).parse_args(argv)
    stream = stdout if stdout is not None else sys.stdout
    operation = Operation(args.operation)
    active_registry = registry
    if registry is DEFAULT_REGISTRY:
        active_registry = create_default_registry(
            ollama_base_url=args.ollama_base_url,
            ollama_timeout=args.ollama_timeout,
            lm_studio_base_url=args.lm_studio_base_url,
            lm_studio_timeout=args.lm_studio_timeout,
            lm_studio_model_roots=(
                tuple(args.lm_studio_model_roots)
                if args.lm_studio_model_roots is not None
                else None
            ),
            docker_timeout=args.docker_timeout,
            docker_classify_ai=args.docker_ai_heuristic,
        )
    provider_names = (
        args.providers if args.providers is not None else active_registry.names
    )
    results = collect_results(active_registry, provider_names, operation)

    if args.output == "json":
        _write_json(stream, operation, results)
    else:
        _write_text(stream, results)
    return _exit_code(results)

